window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c5fb1d753fab393c"]={"versions": [{"id": "FIG-c5fb1d753fab393c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Layout-Transformation / Protokoll-Frame-Kapselungsdiagramm (Mapping ungesicherter auf gesicherte RTPS-Nachrichtenformate).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die Transformation einer ungesicherten RTPS-Nachricht (Real-Time Publish-Subscribe) in eine kryptografisch geschützte RTPS-Nachricht auf Wire-Ebene im AUTOSAR Classic Platform DDS-Modul (<code>AUTOSAR_CP_SWS_DataDistributionService</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Realisierung der OMG DDS-Security-Kapselung zur Gewährleistung von Nachrichtenauthentizität, Datenintegrität und Gruppenauthentifizierung auf <code>DomainParticipant</code>-Ebene unter Anbindung an den AUTOSAR Crypto Service Manager (CSM).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ungesicherte RTPS-Nachricht (Plaintext Frame):</strong></li>\n<li><code>RTPS Header</code>: Globaler Protokoll-Header (ProtocolId, ProtocolVersion, VendorId, GuidPrefix).</li>\n<li><code>RTPS SubMessage</code> (1..n): Nutzdaten- und Steuer-Submessages (z. B. <code>DATA</code>, <code>HEARTBEAT</code>, <code>ACKNACK</code>, <code>INFO_TS</code>).</li>\n<li><strong>Transformationsoperation:</strong></li>\n<li><code>encode_rtps_message</code>: Schnittstelle des DDS Cryptographic Plugins zur Kapselung und Integritätssicherung der PDU.</li>\n<li><strong>Gesicherte RTPS-Nachricht (Encrypted/Authenticated Frame):</strong></li>\n<li><code>RTPS Header(*)</code>: Angepasster/neuer RTPS-Header der Gesamtnachricht.</li>\n<li><code>RTPS SecureRTPSPrefix</code>: Submessage zur Initiierung des Sicherheitskontexts (enthält Kryptografie-Header, Sequence-Numbers, Session-IDs).</li>\n<li><code>RTPS SecureBody</code>: Container-Submessage zur Kapselung der ursprünglichen Nachrichtenelemente:</li>\n<li><code>INFO_SRC*</code>: Eingebettete Submessage zur Identifikation der Quell-Entity/des ursprünglichen Absenders.</li>\n<li><code>RTPS SubMessage*</code> (1..n): Geschützte Nutz- und Steuer-Submessages der Originalnachricht.</li>\n<li><code>RTPS SecureRTPSPostfix</code>: Abschließende Submessage mit Authentifizierungs-Footern (speichert den über die Gesamtnachricht berechneten Message Authentication Code / MAC).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Serialisierung & Assemblierung:</strong> Der DDS-Stack aggregiert anstehende Submessages zu einer standardkonformen RTPS-Nachricht.</li>\n<li><strong>Konditionale Verzweigung:</strong> Ist DDS-Security für den zugeordneten <code>DomainParticipant</code> statisch aktiviert, wird der Transformationspfad <code>encode_rtps_message</code> durchlaufen; andernfalls erfolgt der Direktexport an den Transport-Layer.</li>\n<li><strong>Kapselung & Signierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erzeugung von <code>RTPS SecureRTPSPrefix</code>.</li>\n<li>Einpacken der Plaintext-Submessages inklusive <code>INFO_SRC*</code> in den <code>RTPS SecureBody</code>.</li>\n<li><strong>CSM-Interaktion:</strong> Übermittlung der zu schützenden PDU-Segmente an den CSM zur MAC-Berechnung über den konfigurierten symmetrischen DomainParticipant-Key-Handle.</li>\n<li>Anfügen des <code>RTPS SecureRTPSPostfix</code> mit dem resultierenden MAC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>PDU-Weitergabe:</strong> Die serialisierte Secure-RTPS-PDU wird an die unteren AUTOSAR-Kommunikationsschichten (SoAd/TcpIp/EthIf) übergeben.</li>\n<li><strong>Empfängerpfad (<code>decode_rtps_message</code>):</strong> Reziproke Validierung des MAC via CSM; bei Integritäts- oder Authentifizierungsfehler wird die Nachricht verworfen und ein Sicherheitsereignis gemeldet (Det/Dem).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Authentifizierungs-Granularität:</strong> Die Absicherung erfolgt ausschließlich auf Ebene des <code>DomainParticipant</code>. Publisher, Subscriber, DataWriter und DataReader besitzen im AUTOSAR-CP-DDS-Subset keine separaten Schlüssel.</li>\n<li><strong>Konfigurationsbindung (Pre-Compile Time):</strong> Sämtliche Sicherheitsparameter (Aktivierungsstatus, MAC-Algorithmen, Key-Referenzen) sind pre-compile festzulegen (Konfigurationsbereich 10.2.3.3.1.4). Laufzeit-Handshakes für Key-Exchange entfallen.</li>\n<li><strong>CSM-Kopplung:</strong> DDS hält keine eigenen symmetrischen Schlüssel im RAM/Flash, sondern nutzt ausschließlich CSM-Key-Handles.</li>\n<li><strong>PDU-Budgetierung & Pufferallokation:</strong> Die Kapselung fügt drei Submessages (<code>Prefix</code>, <code>Body</code>-Wrapper inkl. <code>INFO_SRC</code>, <code>Postfix</code>) hinzu. Stack- und Treiber-Entwickler müssen diesen Byte-Overhead (Prefix-Header + MAC-Länge) bei der MTU-Auslegung, Socket-Pufferdimensionierung und SoAd-PDU-Länge statisch vorhalten, um Fragmentierung oder Pufferüberläufe zu verhindern.</li>\n<li><strong>Laufzeit-Performance:</strong> Da standardmäßig ein MAC über die gesamte RTPS-Nachricht generiert wird, ist auf ressourcenlimitierten Mikrocontrollern eine Hardware-Krypto-Beschleunigung (z. B. HSE / Crypto-Hardware über CSM/Crypto-Treiber) zwingend einzuplanen.</li>\n</ul>"}, {"id": "FIG-223b714f0d0a1ff2", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> PDU-Layout-Transformation / Protokoll-Frame-Kapselungsdiagramm (Mapping ungesicherter auf gesicherte RTPS-Nachrichtenformate).</li>\n<li><strong>Technischer Zweck:</strong> Spezifiziert die Transformation einer ungesicherten RTPS-Nachricht (Real-Time Publish-Subscribe) in eine kryptografisch geschützte RTPS-Nachricht auf Wire-Ebene im AUTOSAR Classic Platform DDS-Modul (<code>AUTOSAR_CP_SWS_DataDistributionService</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Realisierung der OMG DDS-Security-Kapselung zur Gewährleistung von Nachrichtenauthentizität, Datenintegrität und Gruppenauthentifizierung auf <code>DomainParticipant</code>-Ebene unter Anbindung an den AUTOSAR Crypto Service Manager (CSM).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Ungesicherte RTPS-Nachricht (Plaintext Frame):</strong></li>\n<li><code>RTPS Header</code>: Globaler Protokoll-Header (ProtocolId, ProtocolVersion, VendorId, GuidPrefix).</li>\n<li><code>RTPS SubMessage</code> (1..n): Nutzdaten- und Steuer-Submessages (z. B. <code>DATA</code>, <code>HEARTBEAT</code>, <code>ACKNACK</code>, <code>INFO_TS</code>).</li>\n<li><strong>Transformationsoperation:</strong></li>\n<li><code>encode_rtps_message</code>: Schnittstelle des DDS Cryptographic Plugins zur Kapselung und Integritätssicherung der PDU.</li>\n<li><strong>Gesicherte RTPS-Nachricht (Encrypted/Authenticated Frame):</strong></li>\n<li><code>RTPS Header(*)</code>: Angepasster/neuer RTPS-Header der Gesamtnachricht.</li>\n<li><code>RTPS SecureRTPSPrefix</code>: Submessage zur Initiierung des Sicherheitskontexts (enthält Kryptografie-Header, Sequence-Numbers, Session-IDs).</li>\n<li><code>RTPS SecureBody</code>: Container-Submessage zur Kapselung der ursprünglichen Nachrichtenelemente:</li>\n<li><code>INFO_SRC*</code>: Eingebettete Submessage zur Identifikation der Quell-Entity/des ursprünglichen Absenders.</li>\n<li><code>RTPS SubMessage*</code> (1..n): Geschützte Nutz- und Steuer-Submessages der Originalnachricht.</li>\n<li><code>RTPS SecureRTPSPostfix</code>: Abschließende Submessage mit Authentifizierungs-Footern (speichert den über die Gesamtnachricht berechneten Message Authentication Code / MAC).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Serialisierung & Assemblierung:</strong> Der DDS-Stack aggregiert anstehende Submessages zu einer standardkonformen RTPS-Nachricht.</li>\n<li><strong>Konditionale Verzweigung:</strong> Ist DDS-Security für den zugeordneten <code>DomainParticipant</code> statisch aktiviert, wird der Transformationspfad <code>encode_rtps_message</code> durchlaufen; andernfalls erfolgt der Direktexport an den Transport-Layer.</li>\n<li><strong>Kapselung & Signierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erzeugung von <code>RTPS SecureRTPSPrefix</code>.</li>\n<li>Einpacken der Plaintext-Submessages inklusive <code>INFO_SRC*</code> in den <code>RTPS SecureBody</code>.</li>\n<li><strong>CSM-Interaktion:</strong> Übermittlung der zu schützenden PDU-Segmente an den CSM zur MAC-Berechnung über den konfigurierten symmetrischen DomainParticipant-Key-Handle.</li>\n<li>Anfügen des <code>RTPS SecureRTPSPostfix</code> mit dem resultierenden MAC.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>PDU-Weitergabe:</strong> Die serialisierte Secure-RTPS-PDU wird an die unteren AUTOSAR-Kommunikationsschichten (SoAd/TcpIp/EthIf) übergeben.</li>\n<li><strong>Empfängerpfad (<code>decode_rtps_message</code>):</strong> Reziproke Validierung des MAC via CSM; bei Integritäts- oder Authentifizierungsfehler wird die Nachricht verworfen und ein Sicherheitsereignis gemeldet (Det/Dem).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Authentifizierungs-Granularität:</strong> Die Absicherung erfolgt ausschließlich auf Ebene des <code>DomainParticipant</code>. Publisher, Subscriber, DataWriter und DataReader besitzen im AUTOSAR-CP-DDS-Subset keine separaten Schlüssel.</li>\n<li><strong>Konfigurationsbindung (Pre-Compile Time):</strong> Sämtliche Sicherheitsparameter (Aktivierungsstatus, MAC-Algorithmen, Key-Referenzen) sind pre-compile festzulegen (Konfigurationsbereich 10.2.3.3.1.4). Laufzeit-Handshakes für Key-Exchange entfallen.</li>\n<li><strong>CSM-Kopplung:</strong> DDS hält keine eigenen symmetrischen Schlüssel im RAM/Flash, sondern nutzt ausschließlich CSM-Key-Handles.</li>\n<li><strong>PDU-Budgetierung & Pufferallokation:</strong> Die Kapselung fügt drei Submessages (<code>Prefix</code>, <code>Body</code>-Wrapper inkl. <code>INFO_SRC</code>, <code>Postfix</code>) hinzu. Stack- und Treiber-Entwickler müssen diesen Byte-Overhead (Prefix-Header + MAC-Länge) bei der MTU-Auslegung, Socket-Pufferdimensionierung und SoAd-PDU-Länge statisch vorhalten, um Fragmentierung oder Pufferüberläufe zu verhindern.</li>\n<li><strong>Laufzeit-Performance:</strong> Da standardmäßig ein MAC über die gesamte RTPS-Nachricht generiert wird, ist auf ressourcenlimitierten Mikrocontrollern eine Hardware-Krypto-Beschleunigung (z. B. HSE / Crypto-Hardware über CSM/Crypto-Treiber) zwingend einzuplanen.</li>\n</ul>"}], "trans": [{"from": "FIG-c5fb1d753fab393c", "to": "FIG-223b714f0d0a1ff2", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
